'use strict';
let state=ForestJourney.initial(),previousResult=null;
const app=document.getElementById('app'),euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n),num=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(n);
const briefings={1:{title:'Schicht 1 · Erst planen, dann Maschinen schicken',text:'Vier Schichten, zwei Maschinen: Stelle 600 fm bereit, davon 360 fm Sägeholz. Im Talgrund liegen bereits 80 fm Waldlager. Prüfe, wo dein Forwarder sofort arbeiten kann.'},2:{title:'Schicht 2 · Zeitdruck und Erkundungslücke',text:'Regen im Talgrund. Die Revierleitung hat nur 3 Stunden Zeit. Dort sind erst 65 % der Fläche erkundet. Eine digitale Bestätigung ersetzt die fehlende Begehung nicht.'},3:{title:'Schicht 3 · Das Sägewerk ändert den Auftrag',text:'Neue Längenvorgaben gelten ab jetzt. Alte Maschineneinstellungen passen möglicherweise nicht mehr. Prüfe den aktuellen Auftrag oder riskiere eine Abwertung.'},4:{title:'Schicht 4 · Das Bereitstellungsfenster schließt',text:'Nutze vorhandenes Waldlager und sichere das Sägeholzziel. Optional kannst du eine zusätzliche Zusage für 180 fm in dieser Schicht abgeben.'}};
function stat(label,value,extra=''){return `<div class="stat"><span class="label">${label}</span><div class="value">${value}</div>${extra}</div>`;}
function dashboard(){const target=ForestGame.targets(state);return `<div class="stats game-stats">${stat('Bereitgestellt',`${num(state.forwarded)} <small>/ ${target.volume} fm</small>`,`<span class="stat-sub">Sägeholz ${num(state.sawForwarded)} / ${target.saw} fm</span><div class="meter"><i style="width:${Math.min(100,state.forwarded/target.volume*100)}%"></i></div>`)}${stat('Vorläufiger Polterwert − Kosten',euro(state.revenue-state.cost),'<span class="stat-sub">Noch kein abgerechneter Liefererlös</span>')}${stat('Bezahlter Stillstand',num(state.idleHours)+' <small>h</small>','<span class="stat-sub">Harvester + Forwarder</span>')}${stat('Boden / Vertrauen',state.soil+' <small>/</small> '+state.reputation,'<span class="stat-sub">Jeweils maximal 100</span>')}</div>`;}
function heading(title,description){return `<div class="intro"><div><p class="eyebrow">Trimble Forestry · INTERFORST · Holzernte</p><h1>${title}</h1><p>${description}</p></div><div class="rounds" aria-label="Schicht ${state.round} von 4">${[1,2,3,4].map(i=>`<span class="round ${state.phase==='result'||i<state.round?'done':i===state.round?'active':''}">${i<state.round||state.phase==='result'?'✓':i}</span>`).join('')}</div></div>`;}
function siteChoice(type,name){return `<label class="fleet-assign"><b>${name}</b><select data-choice="${type}" aria-label="Arbeitsauftrag ${name}">${state.stands.map(s=>`<option value="${s.id}" ${state[type]===s.id?'selected':''} ${s.closed?'disabled':''}>${s.name}${s.closed?' · GESPERRT':' · '+num(s.stock)+' fm Waldlager'}</option>`).join('')}</select></label>`;}
function fleetOverview(){const p=ForestGame.schedule(state),h=state.stands.find(x=>x.id===state.harvester),f=state.stands.find(x=>x.id===state.forwarder);return `<section class="fleet-panel"><div class="panel-title"><h2>Deine Flotte</h2><span>Schichtdauer 8 h</span></div><div class="fleet-assignments">${siteChoice('harvester','H-01 · Harvester')}${siteChoice('forwarder','F-01 · Forwarder')}</div><div class="fleet-mini"><div><span>Harvester geplant ab</span><b>${num(Math.min(8,p.hStart))} h</b><small>${num(h.remaining)} fm stehend · Vorgabe ${ForestGame.gradeSpec(state)} m</small></div><div><span>Forwarder disponiert ab</span><b>${p.fDispatch>=8?'nicht verlegt':num(p.fDispatch)+' h'}</b><small>${num(f.stock)} fm verfügbar vor Schichtbeginn</small></div></div><div class="forester-load ${p.fieldHours>3?'overbooked':''}"><span>Revierleitung vor Ort</span><b>${num(p.fieldHours)} / 3 h</b><small>${p.fieldHours>3?'Überbucht: zusätzliche Wartezeit entsteht.':'Vor-Ort-Zeit für Übergabe, Grenzprüfung und Erkundung.'}</small></div></section>`;}
function render(){renderScreen();if(typeof SceneExperience!=='undefined')SceneExperience.mount(state,app);}
function renderScreen(){renderJourneyNav();if(state.phase==='forest')return renderForestPlanning();if(state.phase==='logistics')return renderLogistics();if(state.phase==='logisticsReceipt')return renderLogisticsReceipt();if(state.phase==='settlement')return renderSettlement();if(state.phase==='result'&&state.journey)return renderJourneyResult();const openGroups=[...app.querySelectorAll('details[data-group][open]')].map(x=>x.dataset.group);if(state.phase==='receipt')return renderReceipt();if(state.phase==='result')return renderResult();const briefing={...briefings[state.round]},error=ForestGame.validate(state),partial=state.stands.some(x=>[state.harvester,state.forwarder].includes(x.id)&&x.surveyCoverage<100);if(state.round===1&&state.journey)briefing.text=`Dein Vertrag: ${ForestGame.targets(state).volume} fm, davon ${ForestGame.targets(state).saw} fm Sägeholz. Nach vier Ernteschichten folgen Lkw-Abfuhr und Abrechnung. Im Talgrund liegen bereits 80 fm Waldlager.`;if(state.round===2&&state.stands.find(x=>x.id==='b').surveyCoverage===100)briefing.text='Regen im Talgrund. Die Nacher­kundung ist dokumentiert. Beachte die ergänzten Schutzbereiche und die knappe Zeit der Revierleitung.';app.innerHTML=heading('Jede Entscheidung zählt.','Plane Holzfluss, Qualität und Maschineneinsatz über vier Schichten.')+dashboard()+`<div class="shift-brief"><span class="shift-number">0${state.round}</span><div><h2>${briefing.title}</h2><p>${briefing.text}</p></div></div><div class="planning-grid"><div class="worksite-column">${fleetOverview()}${overviewMap()}<div class="handover-strip"><span><b>Digitaler Arbeitsauftrag</b><small>Arbeitskarte, 3D-Routen, Sortimente und Erkundungsstand prüfen.</small></span><button class="secondary" id="openHandover">Hiebsübergabe öffnen</button></div></div><section class="decision-column" aria-label="Einsatzplanung">${planTotal('Geplante Kosten dieser Schicht',ForestGame.previewCost(state).total,'shift-'+state.round)}<details class="decision-group" data-group="dispatch" open><summary><span>01</span> Übergabe und Disposition</summary>${toggleChoice('game','handoverMode','Wie kommt der Auftrag zur Maschine?')}${toggleChoice('game','forwardStart','Wann soll der Forwarder los?')}${toggleChoice('game','reporting','Produktionsmeldungen')}</details><details class="decision-group" data-group="quality" ${openGroups.includes('quality')||state.round===3?'open':''}><summary><span>02</span> Sortiment und Maschinenarbeit</summary><div class="spec-alert"><b>Aktuell: ${ForestGame.gradeSpec(state)} m Sägeholz</b><small>Geladene Einstellung: ${state.loadedGrade} m · ${state.round>=3?'Auftrag wurde geändert':'Auftrag nach Bestand'}</small></div>${toggleChoice('game','cutting','Längenvorgabe am Harvester')}${toggleChoice('game','quality','Qualitätskontrolle')}${toggleChoice('game','pace','Arbeitstempo')}</details><details class="decision-group" data-group="nature" ${openGroups.includes('nature')||partial?'open':''}><summary><span>03</span> Grenzen und Naturschutz</summary>${toggleChoice('game','boundary','Flurkarte / Hiebsgrenze an der Maschine')}<div class="boundary-plan-note">${state.stands.filter(x=>[state.harvester,state.forwarder].includes(x.id)).map(x=>x.name+': '+(state.boundaryChecked[x.id]?'Grenze bereits abgeglichen':state.boundary==='digital'?'geprüfter digitaler Hiebsplan gewählt':state.boundary==='field'?'Grenzabgleich eingeplant':'ungeprüft')).join(' · ')}</div><p class="decision-note">${partial?'Talgrund: 35 % der Fläche wurden aus Zeitmangel nicht begangen. Entscheide, wie du mit der Lücke umgehst.':'Für die gewählten Bestände ist die bekannte Erkundung vollständig. Markierte Schutzbereiche bleiben ausgeschlossen.'}</p>${toggleChoice('game','survey','Umgang mit einer ungeprüften Teilfläche')}</details>${state.round===4?`<details class="decision-group" open><summary><span>04</span> Zusätzliche Zusage</summary>${toggleChoice('game','priority','Zusatzauftrag')}</details>`:''}<div class="dispatch-box"><p id="planError" class="${error?'plan-error':'plan-ready'}" role="status">${error||'Disposition vollständig. Starte deine Schicht.'}</p>${error&&state.handoverMode==='digital'?'<button class="secondary" id="fixHandover">Fehlende Übergabe öffnen</button>':''}<button class="primary" id="run" ${error?'disabled':''}>Schicht ${state.round} ausführen</button><small>Szenariosimulation · 8-h-Schicht in 15-Minuten-Schritten. Zeiten und Kosten sind Spielannahmen.</small></div></section></div>`;bindPlanning();}
function bindPlanning(){app.querySelectorAll('[data-choice]').forEach(el=>{if(el.dataset.scope)return;el.onchange=()=>{state[el.dataset.choice]=el.value;render();const target=app.querySelector(`[data-choice="${el.dataset.choice}"]`);target?.focus();};});bindToggles();app.querySelectorAll('[data-plot]').forEach(g=>{const pick=()=>{const id=g.dataset.plot;if(state.stands.find(s=>s.id===id).closed)return;state.harvester=state.forwarder=id;render();};g.onclick=pick;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();}};});app.querySelectorAll('[data-handover],[data-bio]').forEach(g=>{const open=()=>openHandover(g.dataset.handover||g.dataset.bio);g.onclick=open;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};});document.getElementById('openHandover').onclick=()=>openHandover(state.harvester);const fix=document.getElementById('fixHandover');if(fix)fix.onclick=()=>openHandover([state.harvester,state.forwarder].find(id=>!state.handoverAccepted[id]||state.handoverVersions[id]<(state.round>=3?2:1))||state.harvester);document.getElementById('run').onclick=()=>{const error=ForestGame.validate(state);if(error)return;state=ForestGame.calculate(state).next;render();window.scrollTo({top:0,behavior:'smooth'});};}
const timelineNames={work:'Produktiv',wait:'Übergabe / Prüfung',empty:'Kein Arbeitsvorrat',move:'Verlegung',off:'Nicht gebucht',blocked:'Hieb gesperrt',boundary:'Stopp zur Grenzklärung'};
function timeline(r){return `<section class="fleet-panel"><div class="panel-title"><h2>Was haben die Maschinen tatsächlich gemacht?</h2><span>0 bis 8 Stunden</span></div>${['h','f'].map(key=>{const f=r.fleet[key];return `<div class="timeline-row"><div class="timeline-label"><b>${key==='h'?'H-01 · Harvester':'F-01 · Forwarder'}</b><span>${f.site} · ${f.status}</span></div><div class="timeline-track" aria-label="${key==='h'?'Harvester':'Forwarder'}: ${num(f.work)} Stunden produktiv, ${num(f.idle)} Stunden Stillstand">${r.timeline[key].map((status,i)=>`<span class="slot ${status}" title="${num(i/4)}–${num((i+1)/4)} h: ${timelineNames[status]}"></span>`).join('')}</div><div class="timeline-metrics"><span><b>${num(f.work)} h</b> produktiv</span><span><b>${num(f.idle)} h</b> Stillstand</span><span><b>${euro(f.idle*f.rate)}</b> Stillstandskosten enthalten</span></div></div>`;}).join('')}<div class="timeline-legend">${Object.entries(timelineNames).map(([key,name])=>`<span><i class="${key}"></i>${name}</span>`).join('')}</div></section>`;}
function renderReceipt(){const r=state.history.at(-1);app.innerHTML=`<div class="result-wrap wide-result">${heading('Deine Schicht. Die Folgen.','Produktionsbericht, Maschinenzeiten und Kosten im gemeinsamen Überblick.')}${dashboard()}${r.logs.some(x=>x.kind==='incident')?'<div class="shutdown-banner"><b>HIEB GESPERRT</b><p>Ein übergangener Naturhinweis hat den gesamten betroffenen Hieb gestoppt. Du musst die nächste Schicht auf einem anderen Hieb planen.</p></div>':''}<div class="receipt-summary">${stat('Diese Schicht gerückt',num(r.forwarded)+' <small>fm</small>')}${stat('Davon Sägeholz',num(r.sawForwarded)+' <small>fm</small>')}${stat('Neu abgewertet',num(r.downgraded)+' <small>fm</small>')}${stat('Wertbeitrag Schicht',euro(r.margin))}</div>${timeline(r)}<div class="report-columns"><section class="receipt"><h2>Entscheidungen und Folgen</h2><div class="event-log">${r.logs.map(l=>`<article class="log-card ${l.kind}"><b>${l.title}</b><p>${l.text}</p></article>`).join('')}</div></section><section class="receipt"><h2>Kosten dieser Schicht</h2><dl class="cost-ledger">${r.costItems.map(x=>`<div><dt>${x.label}</dt><dd>${euro(x.value)}</dd></div>`).join('')}<div class="ledger-total"><dt>Gesamtkosten</dt><dd>${euro(r.cost)}</dd></div><div><dt>Vorläufiger Holzwert / Spielbonus</dt><dd>${euro(r.revenue)}</dd></div></dl><p class="report-note">Stillstandskosten sind in den gebuchten Maschinenstunden enthalten. Der niedrigere Erlös abgewerteten Holzes wird nicht nochmals als Kosten abgezogen.</p><div class="material-balance"><b>${num(r.harvest)} fm geerntet</b><span>${num(r.forwarded)} fm gerückt zum Polter P-${r.forwardOrigin.toUpperCase()}01</span>${r.neighbourVolume?`<span class="neighbour-volume">${num(r.neighbourVolume)} fm Nachbarholz gesondert · nicht angerechnet</span>`:''}<span>${num(state.stands.reduce((a,b)=>a+b.stock,0))} fm verbleiben als Waldlager</span></div></section></div><div class="actions"><button class="primary" id="next">${state.round===4?(state.journey?'Lkw-Logistik planen':'Gesamtauswertung und Praxisbezug'):'Schicht '+(state.round+1)+' planen'}</button><button class="secondary" id="receiptHandover">Arbeitsauftrag ansehen</button></div></div>`;document.getElementById('next').onclick=()=>{state=ForestGame.nextShift(state);render();window.scrollTo({top:0,behavior:'smooth'});};document.getElementById('receiptHandover').onclick=()=>openHandover(r.harvestOrigin);}
function opportunities(){const rows=[{value:state.boundaryIncidents*3200,title:'Geprüfte Hiebsgrenzen bis zur Maschine',fact:'Vernetzte Planung unterstützt gemeinsame Karten und Kartenebenen. Der Auftraggeber muss die richtige Hiebsgrenze und Freigabe bereitstellen.',question:'Hat euer Fahrer den aktuellen, geprüften Hiebsplan an Bord – oder nur eine alte Skizze?'},{value:state.history.reduce((a,r)=>a+r.fleet.f.idle*140,0),title:'Forwarder passend zum Holzbestand disponieren',fact:'Digitale Produktionsmeldungen führen geerntete, gerückte und verbleibende Mengen je Produkt zusammen.',question:'Wie früh sieht eure Disposition, wo tatsächlich rückbares Holz liegt?'},{value:state.missedValue,title:'Aktuelle Sortimentsvorgaben bis zur Maschine',fact:'Das Datenblatt beschreibt Produktanweisungen für den Harvester und die Verarbeitung von Kontrollmessungen.',question:'Wie stellt ihr sicher, dass die Maschine nach dem aktuellsten Auftrag arbeitet?'},{value:state.history.filter(r=>r.decisions.handoverMode==='manual').reduce((a,r)=>a+r.plan.brief*(180+140),0),title:'Arbeitsauftrag, Karte und Hinweise gemeinsam bereitstellen',fact:'Planning-, On-Board- und Field-Operation-App nutzen gemeinsame Arbeitsgebietsinformationen und Karten.',question:'Was muss die Revierleitung heute noch persönlich erklären, obwohl es bereits dokumentiert ist?'},{value:state.closedSites.length*5200,title:'Erkundungslücken sichtbar lassen und nachverfolgen',fact:'Standortvorbereitung, eigene Kartensymbole, Kommunikation und Audits unterstützen den Informationsfluss.',question:'Wie verhindert ihr, dass ein ungeprüfter Bereich als freigegeben verstanden wird?'}];return rows.sort((a,b)=>b.value-a.value);}
function renderResult(){const score=ForestGame.score(state),parts=ForestGame.breakdown(state),opps=opportunities();app.innerHTML=`<div class="result-wrap wide-result">${heading('So gut war deine Planung.','Vier Schichten. Fünf Bewertungsbereiche. Ein Gespräch über euren Alltag.')}<section class="receipt final-score"><div class="summary"><div class="score"><strong>${score}</strong><span>von 1.000 Punkten</span></div><div><p class="eyebrow">${score>=800?'Vernetzt geplant':score>=600?'Solide disponiert':'Hier liegt Verbesserungspotenzial'}</p><h2>${num(state.forwarded)} fm bereitgestellt · ${euro(state.revenue-state.cost)} Wertbeitrag</h2><p>${num(state.idleHours)} bezahlte Stillstandsstunden · ${num(state.downgraded)} fm abgewertet · ${state.closedSites.length} Hieb gesperrt · ${num(state.neighbourVolume)} fm Nachbarholz ohne Auftragsgutschrift.</p>${previousResult?`<p class="previous-score">Vorherige Runde: ${previousResult.score} Punkte · jetzt ${score-previousResult.score>=0?'+':''}${score-previousResult.score} Punkte.</p>`:''}</div></div><div class="score-breakdown">${parts.map(p=>`<div><b>${p.name}</b><strong>${p.points}<small> / ${p.max}</small></strong><div class="meter"><i style="width:${p.points/p.max*100}%"></i></div><p>${p.detail}</p></div>`).join('')}</div></section><section class="conversation"><p class="eyebrow">Dein stärkster Gesprächseinstieg</p><h2>„${opps[0].question}“</h2><p>Welche Information hätte eure letzte ungeplante Maschinenstunde verhindert?</p></section><div class="cf-connections">${opps.map(o=>`<article><p class="eyebrow">Vernetzte Holzernte im Arbeitsablauf</p><h3>${o.title}</h3><p>${o.fact}</p><p class="connection-question">${o.question}</p></article>`).join('')}</div><details class="scoring-rules"><summary>Wie entstehen die 1.000 Punkte?</summary><p>Auftrag: 300 Punkte, gewichtet zu 60 % nach 600 fm Gesamtmenge und 40 % nach 360 fm Sägeholz. Wertbeitrag: 250 Punkte bei 22.000 €. Qualität: 200 Punkte für den Anteil nicht abgewerteten potenziellen Sägeholzes. Maschinennutzung: 150 Punkte für produktive geteilt durch gebuchte Stunden. Boden und Vertrauen: 100 Punkte, gewichtet 40/60. Jeder Teil ist auf seinen Höchstwert begrenzt.</p><p>Leistung und Kosten sind transparente Szenarioannahmen (siehe Spielregeln), keine allgemeingültigen Branchenwerte. Die Eurobeträge sind keine ROI-Prognose. Digitalisierung ersetzt weder eine Begehung noch eine fachliche Freigabe.</p></details><div class="actions"><button class="primary" id="improve">Mit vernetzter Planung erneut spielen</button><button class="secondary" id="restart">Nächster Gast · neu beginnen</button><button class="secondary" id="review">Vier Schichten vergleichen</button></div><div id="history"></div><p class="source-note">Das Spiel ist eine eigenständige Messedemonstration.</p></div>`;document.getElementById('restart').onclick=()=>{previousResult=null;state=ForestGame.initial();render();window.scrollTo({top:0,behavior:'smooth'});};document.getElementById('improve').onclick=()=>{previousResult={score};state=ForestGame.initial();Object.assign(state,{handoverMode:'digital',forwardStart:'stock',cutting:'current',quality:'check',reporting:'live',survey:'protect',boundary:'digital'});render();window.scrollTo({top:0,behavior:'smooth'});};document.getElementById('review').onclick=()=>{const target=document.getElementById('history');target.innerHTML=target.innerHTML?'':`<section class="receipt"><h2>Vier Schichten im Vergleich</h2><div class="history-table-wrap"><table><thead><tr><th>Schicht</th><th>Gerückt</th><th>Sägeholz</th><th>Abgewertet</th><th>Stillstand</th><th>Wertbeitrag</th></tr></thead><tbody>${state.history.map(r=>`<tr><td>${r.round}</td><td>${num(r.forwarded)} fm</td><td>${num(r.sawForwarded)} fm</td><td>${num(r.downgraded)} fm</td><td>${num(r.fleet.h.idle+r.fleet.f.idle)} h</td><td>${euro(r.margin)}</td></tr>`).join('')}</tbody></table></div></section>`;target.scrollIntoView({behavior:'smooth',block:'nearest'});};}
document.getElementById('handoverButton').onclick=()=>openHandover(state.harvester);document.getElementById('help').onclick=()=>document.getElementById('rules').showModal();document.getElementById('closeHelp').onclick=document.getElementById('understood').onclick=()=>document.getElementById('rules').close();render();
const context=document.modelContext;if(context?.registerTool){for(const tool of [{name:'read_forestry_game',title:'Spielstand lesen',description:'Liest Planung, Flotte, Hiebsstatus, Mengen und Punktestand.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({state:structuredClone(state),score:state.journey?ForestJourney.score(state):ForestGame.score(state),breakdown:state.journey?ForestJourney.breakdown(state):ForestGame.breakdown(state)})},{name:'configure_forestry_shift',title:'Schicht planen',description:'Ändert Bestand und Tempo ohne Schichtstart oder Übergabebestätigung.',inputSchema:{type:'object',properties:{harvester:{type:'string',enum:['a','b','c']},forwarder:{type:'string',enum:['a','b','c']},pace:{type:'string',enum:['careful','normal','fast']}},required:['harvester','forwarder','pace'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:i=>{if(state.phase!=='plan'||!i||!['a','b','c'].includes(i.harvester)||!['a','b','c'].includes(i.forwarder)||!Object.hasOwn(ForestGame.paces,i.pace)||[i.harvester,i.forwarder].some(id=>state.stands.find(s=>s.id===id).closed))throw Error('Ungültige oder gesperrte Planung.');Object.assign(state,{harvester:i.harvester,forwarder:i.forwarder,pace:i.pace});render();return{round:state.round,harvester:state.harvester,forwarder:state.forwarder,pace:state.pace};}}])try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}}
